Method.Source:
protected void init()
{
    api = XAPI_APIS::CreateAgreement;
    super();
}

protected void postRun()
{
    EGS_API_DataContract_Response res;

    if (!responseText)
    {
        return;
    }

    res      = FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseText);
    logKey   = "AgreementNum";
    logValue = res.parmMessage();
}

protected str body()
{
    CustTable   custTable;
    Map         configMap;
    str         custAccount;

    custAccount = XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, 'CustAccount');
    custTable   = CustTable::find(custAccount);

    configMap = new Map(Types::String, Types::String);
    configMap.insert('<DataAreaId>',                curExt());
    configMap.insert('<AlternativeCustomerNumber>', custTable.EXU_AlternativeCustomerNumber);
    configMap.insert('<MeteringPoint>',             XAPI_MeteringPointGenerator::generateMeteringPoint());

    return this.prepareBody(configMap);
}
